	ftPath(pa, 1, 2, 25000, 30000, 35000, 34000, -1, 0, 16)
	ftPath(pa, 1, 1, 20000, 31960, 25000, 32040, -1, 0, 16)
	ftPath(pa, 1, 4, 24400, 31700, 25000, 32300, 0, -1, 8)
	ftWord(fw, et, 1, 12000, 31000, 15000, 32000, 67, 108)
	ftWord(fw, et, 1, 28000, 31000, 31000, 32000, 83, 118)
	pk = ftKind(pa, fw, fl, et, ws, 9800, 29800, 35200, 34200, 79200)
