func TestARasterIsAPhotographACodeAScreenshotALogoOrLineArtByItsBitsAndItsShape(emonT *testing.T) {
	var fi *port.Cells = port.NewCells()
	ftFi(fi, 1, 7, 2, 3, 8, 300, 0)
	port.AssertEq(emonT, figclass.FcImageKind(fi, 0, 20000, 15000, 20000, 35000, 79200, 0)/1024, model.FgPhoto(), "a JPEG that needed three bits a pixel")
	port.AssertThat(emonT, (figclass.FcImageKind(fi, 0, 20000, 15000, 20000, 35000, 79200, 0)%1024) >= 600, "a sure one")
	ftFi(fi, 1, 0, 2, 3, 8, 60, 0)
	port.AssertEq(emonT, figclass.FcImageKind(fi, 0, 30000, 20000, 20000, 40000, 79200, 0)/1024, model.FgScreenshot(), "a large flat one")
	port.AssertThat(emonT, (figclass.FcImageKind(fi, 0, 30000, 20000, 20000, 40000, 79200, 0)%1024) < 500, "which is not sure enough for a figure with no caption")
	port.AssertEq(emonT, figclass.FcImageKind(fi, 0, 4000, 4000, 5000, 9000, 79200, 0)/1024, model.FgLogo(), "a small flat one at the head of the page")
	port.AssertEq(emonT, figclass.FcImageKind(fi, 0, 4000, 4000, 30000, 34000, 79200, 0)/1024, model.FgUnknown(), "and in the middle of it")
	ftFi(fi, 1, 9, 1, 1, 1, 20, 0)
	port.AssertEq(emonT, figclass.FcImageKind(fi, 0, 20000, 5000, 20000, 25000, 79200, 0)/1024, model.FgBarcode(), "a two-colour one far wider than high")
	port.AssertEq(emonT, figclass.FcImageKind(fi, 0, 8000, 8000, 20000, 28000, 79200, 0)/1024, model.FgQr(), "a square two-colour one")
	port.AssertEq(emonT, figclass.FcImageKind(fi, 0, 12000, 8000, 20000, 28000, 79200, 0)/1024, model.FgIllustration(), "any other two-colour one is line art")
	port.AssertEq(emonT, figclass.FcImageKind(fi, 5, 12000, 8000, 20000, 28000, 79200, 0)/1024, model.FgUnknown(), "a placement with no row says nothing")
}

