func ftPara(nodes *port.Cells, regions *port.Cells, text *port.Cells, kind int32, nch int32, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// A node of `kind` with `nch` letters of text and one region on page 1.
	var n int32 = model.NodeNew(nodes, kind, 0)
	var at int32 = port.CellsLen(text)
	var i int32 = 0
	for i < nch {
		model.TextAppendCp(text, 97)
		i += 1
	}
	model.NodeSetText(nodes, n, at, nch)
	model.NodeAddRegion(nodes, regions, n, 1, x0, y0, x1, y1)
	return n
}

func TestAShortParagraphOnAFigureIsItsLabelAndALongOneStays(emonT *testing.T) {
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var nn *port.Cells = port.NewCells()
	var na *port.Cells = port.NewCells()
	var nr *port.Cells = port.NewCells()
	var nm *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	var fg *port.Cells = port.NewCells()
	var fd *port.Cells = port.NewCells()
	var ab *port.Cells = port.NewCells()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	model.PageNew(pages, 1, 61200, 79200, 0, model.PkVector())
	ftPara(nodes, regions, text, model.NkParagraph(), 3, 8000, 12000, 9600, 12750)
	ftPara(nodes, regions, text, model.NkParagraph(), 60, 7200, 50000, 54000, 51250)
	ftPara(nodes, regions, text, model.NkParagraph(), 4, 15000, 31000, 17000, 31750)
	ftCand(cand, 1, 10000, 10000, 40000, 30000)
	ftFd(fd, model.FgChart(), 760)
	port.CellsPush(fg, 0)
	port.CellsPush(fg, 0)
	restruct.RsFigures(nodes, attrs, regions, text, nn, na, nr, nm, cand, fg, fd, ab)
	port.AssertEq(emonT, model.NodeCount(nn), 3, "the document, the figure and the long paragraph: the two short ones are labels")
	port.AssertEq(emonT, model.NodeKind(nn, 1), model.NkFigure(), "the figure goes in by its top edge (30000 is above the paragraph at 50000)")
	port.AssertEq(emonT, model.NodeSub(nn, 1), model.FgChart(), "its kind")
	port.AssertEq(emonT, model.NodeConf(nn, 1), 760, "its confidence")
	port.AssertThat(emonT, model.NodeAttr(nn, na, 1, model.FkLabels()) >= 0, "it has labels")
	port.AssertEq(emonT, model.NodeKind(nn, 2), model.NkParagraph(), "the long paragraph is still body text")
}

func TestAFigureGoesInBeforeItsCaptionWhateverItsTopEdgeSays(emonT *testing.T) {
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var nn *port.Cells = port.NewCells()
	var na *port.Cells = port.NewCells()
	var nr *port.Cells = port.NewCells()
	var nm *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	var fg *port.Cells = port.NewCells()
	var fd *port.Cells = port.NewCells()
	var ab *port.Cells = port.NewCells()
	var c int32 = 0
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	model.PageNew(pages, 1, 61200, 79200, 0, model.PkVector())
	// document > paragraph (top), paragraph (far below: the other column), caption (just under the figure)
	ftPara(nodes, regions, text, model.NkParagraph(), 60, 7200, 5000, 54000, 6250)
	ftPara(nodes, regions, text, model.NkParagraph(), 60, 7200, 40000, 54000, 41250)
	c = ftPara(nodes, regions, text, model.NkCaption(), 20, 10000, 31000, 30000, 32000)
	model.NodeSetAux(nodes, c, 1)
	ftCand(cand, 1, 10000, 10000, 30000, 30000)
	ftFd(fd, model.FgChart(), 760)
	port.CellsPush(fg, 0)
	port.CellsPush(fg, 0)
	restruct.RsFigures(nodes, attrs, regions, text, nn, na, nr, nm, cand, fg, fd, ab)
	port.AssertEq(emonT, model.NodeCount(nn), 5, "the document, three blocks and the figure")
	port.AssertEq(emonT, model.NodeKind(nn, 3), model.NkFigure(), "the figure is just before its caption, after the paragraph that is lower on the page")
	port.AssertEq(emonT, model.NodeKind(nn, 4), model.NkCaption(), "and the caption follows it")
}
